css.breakpoint_base:
@font-face{font-family:'Manrope';font-weight:400;font-display:swap;src:url('/wp-content/plugins/tixomat/assets/fonts/manrope/Manrope-400.ttf') format('truetype')}
@font-face{font-family:'Manrope';font-weight:500;font-display:swap;src:url('/wp-content/plugins/tixomat/assets/fonts/manrope/Manrope-500.ttf') format('truetype')}
@font-face{font-family:'Manrope';font-weight:600;font-display:swap;src:url('/wp-content/plugins/tixomat/assets/fonts/manrope/Manrope-600.ttf') format('truetype')}
@font-face{font-family:'Manrope';font-weight:700;font-display:swap;src:url('/wp-content/plugins/tixomat/assets/fonts/manrope/Manrope-700.ttf') format('truetype')}
@font-face{font-family:'Manrope';font-weight:800;font-display:swap;src:url('/wp-content/plugins/tixomat/assets/fonts/manrope/Manrope-800.ttf') format('truetype')}
.breakdance .evs-pg {
  --evs-font: 'Manrope', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --evs-bg: #F2F3F7; --evs-surface: #FFFFFF; --evs-night: #2C2F3F; --evs-text: #2C2F3F; --evs-body: #6B6F82; --evs-muted: #C9CCD6;
  --evs-sep: #E3E5EC; --evs-rowline: #EFEFF1; --evs-red: #FC2F55; --evs-signal: #E8445A; --evs-green: #1F8F5F;
  --evs-orange: #FFB340; --evs-blue: #409CFF; --evs-tint: rgba(232,68,90,.10);
  --evs-r-card: 20px; --evs-r: 12px; --evs-page: 16px; --evs-width: 1180px;
  font-family: var(--evs-font); color: var(--evs-text); -webkit-font-smoothing: antialiased;
}

.breakdance .evs-pg { background: var(--evs-bg); font-size: 14px; line-height: 20px; }
.breakdance .evs-pg.bde-section { padding: 0; }
.breakdance .evs-pg > .section-container { max-width: var(--evs-width); padding: 0 var(--evs-page); }
.breakdance .evs-pg h1, .breakdance .evs-pg h2, .breakdance .evs-pg h3 { font-family: var(--evs-font); margin: 0; color: var(--evs-text); text-wrap: balance; }
.breakdance .evs-pg .bde-div, .breakdance .evs-pg .bde-text, .breakdance .evs-pg .bde-shortcode, .breakdance .evs-pg .bde-button { min-width: 0; }
.breakdance .evs-pg :is(p, .breakdance a, .breakdance span, .breakdance div, .breakdance li, .breakdance button, .breakdance input, .breakdance select, .breakdance textarea, .breakdance b, .breakdance strong, .breakdance label) { font-family: var(--evs-font); }
/* Abschnittstitel wie SectionTitle/EvOpenSection: 20/800, über der Karte, ohne Strich */
.breakdance .evs-h2 { font-size: 20px !important; line-height: 1.25 !important; font-weight: 800 !important; letter-spacing: -.3px; }
.breakdance .evs-card { background: var(--evs-surface); border-radius: var(--evs-r-card); padding: 14px; box-sizing: border-box; width: 100%; }
.breakdance .evs-sechead { display: flex; flex-direction: row; align-items: baseline; justify-content: space-between; gap: 12px; width: 100%; }
.breakdance .evs-link .button-atom { all: unset; cursor: pointer; font-size: 13px; font-weight: 700; color: var(--evs-signal); white-space: nowrap; }
@media (min-width: 900px) {
  .breakdance .evs-pg { --evs-page: 32px; }
}

.breakdance .evo { position: relative; }
.breakdance .evo > .section-container { position: static; padding-bottom: 120px; }
/* roter Hintergrund oben, die Profilkarte liegt darüber */
.breakdance .evo::before { content: ""; position: absolute; left: 0; right: 0; top: 0; height: 96px; z-index: 0; border-radius: 0 0 28px 28px; background: var(--evs-red); }

/* Profilkarte: Logo 64 (Radius 20), Sparten, Name, „Stadt · Motto“, Eckdaten, Folgen */
.breakdance .evo-card { position: relative; z-index: 1; display: grid; gap: 12px; margin-top: 24px; padding: 16px; background: var(--evs-surface); border-radius: var(--evs-r-card); width: 100%; box-sizing: border-box; }
.breakdance .evo-top { display: flex; flex-direction: row; gap: 14px; align-items: center; width: 100%; }
.breakdance .evo-top > .bde-shortcode { flex: none; width: auto; }
.breakdance .evo-info { flex: 1 1 0; min-width: 0; display: grid; gap: 4px; }
.breakdance .tix-org-logo { width: 64px; height: 64px; border-radius: var(--evs-r-card); overflow: hidden; display: grid; place-items: center; flex: none; background: var(--evs-night); }
.breakdance .tix-org-logo img { width: 100%; height: 100%; object-fit: cover; display: block; }
.breakdance .tix-org-ini { width: 100%; height: 100%; display: grid; place-items: center; color: #fff; background: var(--evs-night); font-weight: 800; font-size: 22px; }
.breakdance .evo-title { font-size: 20px !important; line-height: 1.25 !important; font-weight: 800 !important; letter-spacing: -.3px; overflow-wrap: anywhere; }
.breakdance .tix-org-sub { font-size: 12.5px; color: var(--evs-body); }
.breakdance .tix-pills { display: flex; flex-wrap: wrap; gap: 6px; }
.breakdance .tix-pill { display: inline-flex; padding: 3px 8px; border-radius: 6px; background: var(--evs-signal); color: #fff; font-size: 11px; line-height: 16px; font-weight: 600; letter-spacing: .4px; text-transform: uppercase; }
.breakdance .tix-org-facts { display: flex; flex-wrap: wrap; gap: 6px 16px; color: var(--evs-body); font-size: 12.5px; }
.breakdance .tix-org-facts span { display: inline-flex; gap: 6px; align-items: center; }
.breakdance .tix-org-facts b { color: var(--evs-text); font-weight: 700; }
.breakdance .tix-org-facts svg { width: 14px; height: 14px; }
/* Folgen: Handy als schwebende Leiste unten, Desktop in der Karte */
.breakdance .evo-followbar { position: fixed !important; left: 16px; right: 16px; bottom: calc(16px + env(safe-area-inset-bottom, 0px)); z-index: 60; margin: 0 !important;
  background: var(--evs-surface); border-radius: 24px; padding: 10px; box-shadow: 0 8px 24px rgba(0,0,0,.10); box-sizing: border-box; width: auto; }

/* Abschnitte: Titel 20/800 über weißer Karte */
.breakdance .evo-body { position: relative; z-index: 1; display: grid; gap: 22px; padding-top: 22px; width: 100%; }
.breakdance .evo-main, .breakdance .evo-aside { display: grid; gap: 22px; align-content: start; width: 100%; }
.breakdance .evo-sec { display: grid; gap: 10px; width: 100%; }
.breakdance .tix-org-sec { display: grid; gap: 10px; width: 100%; background: none; padding: 0; }
.breakdance .tix-org-h2 { font-size: 20px !important; line-height: 1.25 !important; font-weight: 800 !important; letter-spacing: -.3px; margin: 0; }
.breakdance .tix-org-desc, .breakdance .tix-chips, .breakdance .tix-crows { background: var(--evs-surface); border-radius: var(--evs-r-card); padding: 14px; box-sizing: border-box; }
.breakdance .tix-org-desc p { margin: 0 0 10px; font-size: 14px; line-height: 20px; color: var(--evs-text); }
.breakdance .tix-org-desc p:last-child { margin-bottom: 0; }
.breakdance .tix-ib { width: 24px; height: 24px; flex: none; border-radius: 50%; background: var(--evs-tint); display: grid; place-items: center; color: var(--evs-signal); }
.breakdance .tix-ib svg { width: 13px; height: 13px; }
.breakdance .tix-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.breakdance .tix-chip { display: inline-flex; align-items: center; gap: 8px; padding: 6px 14px 6px 6px; border-radius: 999px; background: var(--evs-bg); font-size: 14px; font-weight: 600; }
.breakdance .tix-crows { display: grid; padding-top: 2px; padding-bottom: 2px; }
.breakdance .tix-crow { display: flex; align-items: center; gap: 12px; min-height: 48px; color: var(--evs-text); text-decoration: none; }
.breakdance .tix-crow + .tix-crow { background: linear-gradient(var(--evs-rowline), var(--evs-rowline)) right top / calc(100% - 36px) 1px no-repeat; }
.breakdance .tix-crow span:not(.tix-ib) { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 14px; }
.breakdance .tix-chev { width: 14px; height: 14px; color: var(--evs-body); flex: none; }

@media (min-width: 900px) {
  .breakdance .evo::before { height: 140px; }
  .breakdance .evo-card { margin-top: 48px; grid-template-columns: minmax(0, 1fr) 240px; align-items: center; padding: 20px; }
  .breakdance .evo-card > .evo-facts { grid-column: 1; }
  .breakdance .evo-followbar { position: static !important; box-shadow: none; padding: 0; grid-column: 2; grid-row: 1 / span 2; }
  .breakdance .tix-org-logo { width: 96px; height: 96px; }
  .breakdance .evo-title { font-size: 32px !important; }
  .breakdance .evo-body { grid-template-columns: minmax(0, 1fr) 340px; gap: 32px; padding-top: 32px; }
  .breakdance .evo > .section-container { padding-bottom: 64px; }
}
